use vstd::prelude::*;

verus! {

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        result@ == a@,
        result@.len() == a@.len(),
{
    let mut result: Vec<T> = Vec::with_capacity(a.len());

    for &x in a.iter()
        invariant
            result@ == a@.subrange(0, result@.len() as int),
            result@.len() <= a@.len(),
        decreases a@.len() - result@.len(),
    {
        result.push(x);
    }

    result
}

} // verus!

